#pragma once
#ifdef PLATFORM_PC

// Palette loads that copy past the palette's own banks (generated by
// tools/gen_pal_overread.py into platform/pal_overread.c).
struct PcPalOverread {
    const void *pal;  // the palette as the graphics tables name it
    const u16 *rom;   // what the GBA copies from there, ROM bytes included
    u32 size;         // bytes in rom[] (the largest copy of this palette)
};

extern const struct PcPalOverread gPcPalOverreads[];
extern const u32 gPcPalOverreadCount;

#endif
